import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import path from "node:path";

export type BookStatus = "reading" | "finished";

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  addedAt: string;
  finishedAt: string | null;
};

const MAX_TITLE = 200;
const MAX_AUTHOR = 200;
const MAX_NOTES = 5000;

export function booksFilePath(): string {
  return process.env.BOOKS_FILE ?? path.join(process.cwd(), "data", "books.json");
}

let writeChain: Promise<unknown> = Promise.resolve();

function withWriteLock<T>(task: () => Promise<T>): Promise<T> {
  const run = writeChain.then(task, task);
  writeChain = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

export class BookInputError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "BookInputError";
  }
}

function cleanField(value: string, max: number): string {
  return value.trim().slice(0, max);
}

function normalizeBook(value: unknown): Book | null {
  if (!value || typeof value !== "object") return null;
  const book = value as Record<string, unknown>;
  if (typeof book.id !== "string" || book.id.length === 0) return null;
  if (typeof book.title !== "string" || typeof book.author !== "string") return null;
  if (book.status !== "reading" && book.status !== "finished") return null;

  return {
    id: book.id,
    title: book.title,
    author: book.author,
    notes: typeof book.notes === "string" ? book.notes : "",
    status: book.status,
    addedAt: typeof book.addedAt === "string" ? book.addedAt : new Date(0).toISOString(),
    finishedAt: typeof book.finishedAt === "string" ? book.finishedAt : null,
  };
}

async function readStore(): Promise<Book[]> {
  try {
    const raw = await readFile(booksFilePath(), "utf8");
    const parsed = JSON.parse(raw) as { books?: unknown };
    if (!Array.isArray(parsed.books)) return [];
    return parsed.books.flatMap((entry) => {
      const book = normalizeBook(entry);
      return book ? [book] : [];
    });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }
}

async function writeStore(books: Book[]): Promise<void> {
  const file = booksFilePath();
  await mkdir(path.dirname(file), { recursive: true });
  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
  try {
    await writeFile(file, "", { flag: "a" }).catch(() => undefined);
    await writeFile(tmp, `${JSON.stringify({ books }, null, 2)}\n`, "utf8");
    await rename(tmp, file);
  } catch (error) {
    await rm(tmp, { force: true });
    throw error;
  }
}

export async function listBooks(): Promise<Book[]> {
  return readStore();
}

export function readingBooks(books: Book[]): Book[] {
  return books
    .filter((book) => book.status === "reading")
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
}

export function finishedBooks(books: Book[]): Book[] {
  return books
    .filter((book) => book.status === "finished")
    .sort((a, b) => (b.finishedAt ?? b.addedAt).localeCompare(a.finishedAt ?? a.addedAt));
}

export async function getBook(id: string): Promise<Book | null> {
  const books = await readStore();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook(input: {
  title: string;
  author: string;
  notes?: string;
}): Promise<Book> {
  const title = cleanField(input.title, MAX_TITLE);
  const author = cleanField(input.author, MAX_AUTHOR);
  const notes = cleanField(input.notes ?? "", MAX_NOTES);
  if (!title || !author) {
    throw new BookInputError("Title and author are required.");
  }

  const book: Book = {
    id: randomUUID(),
    title,
    author,
    notes,
    status: "reading",
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };

  await withWriteLock(async () => {
    const books = await readStore();
    books.push(book);
    await writeStore(books);
  });

  return book;
}

export async function markBookFinished(id: string): Promise<Book | null> {
  return withWriteLock(async () => {
    const books = await readStore();
    const book = books.find((item) => item.id === id);
    if (!book) return null;
    if (book.status !== "finished") {
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
      await writeStore(books);
    }
    return book;
  });
}

export async function updateBookNotes(id: string, notes: string): Promise<Book | null> {
  const cleaned = cleanField(notes, MAX_NOTES);
  return withWriteLock(async () => {
    const books = await readStore();
    const book = books.find((item) => item.id === id);
    if (!book) return null;
    book.notes = cleaned;
    await writeStore(books);
    return book;
  });
}

