import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { addBook, getBook, listBooks, markBookFinished, updateBookNotes } from "./books";

describe("books file store", () => {
  let dir = "";

  beforeEach(async () => {
    dir = await mkdtemp(path.join(tmpdir(), "books-"));
    process.env.BOOKS_FILE = path.join(dir, "books.json");
  });

  afterEach(async () => {
    delete process.env.BOOKS_FILE;
    await rm(dir, { recursive: true, force: true });
  });

  it("writes a new book to json and reads it back after a fresh load", async () => {
    const created = await addBook({
      title: "  The Dispossessed ",
      author: "Ursula K. Le Guin",
      notes: "Ambiguous utopia.",
    });

    const saved = JSON.parse(await readFile(process.env.BOOKS_FILE!, "utf8")) as {
      books: Array<{ title: string; status: string }>;
    };
    expect(saved.books).toEqual([
      expect.objectContaining({
        id: created.id,
        title: "The Dispossessed",
        author: "Ursula K. Le Guin",
        notes: "Ambiguous utopia.",
        status: "reading",
        finishedAt: null,
      }),
    ]);

    const loaded = await listBooks();
    expect(loaded.map((book) => book.id)).toEqual([created.id]);
    expect((await getBook(created.id))?.title).toBe("The Dispossessed");
  });

  it("keeps earlier books when another is added", async () => {
    await addBook({ title: "Kindred", author: "Octavia E. Butler" });
    await addBook({ title: "Piranesi", author: "Susanna Clarke" });
    expect((await listBooks()).map((book) => book.title)).toEqual(["Kindred", "Piranesi"]);
  });

  it("marks a book finished without dropping notes", async () => {
    const book = await addBook({
      title: "Kindred",
      author: "Octavia E. Butler",
      notes: "Time travel.",
    });

    const finished = await markBookFinished(book.id);
    expect(finished?.status).toBe("finished");
    expect(finished?.finishedAt).toEqual(expect.any(String));
    expect(finished?.notes).toBe("Time travel.");
    expect((await getBook(book.id))?.status).toBe("finished");
  });

  it("updates notes in the same file", async () => {
    const book = await addBook({ title: "Piranesi", author: "Susanna Clarke" });
    await updateBookNotes(book.id, "The house is the world.");
    expect((await getBook(book.id))?.notes).toBe("The house is the world.");
  });

  it("rejects a blank title and does not create the file", async () => {
    await expect(addBook({ title: "   ", author: "Someone" })).rejects.toThrow(/required/i);
    await expect(listBooks()).resolves.toEqual([]);
  });

  it("returns null when the book id is unknown", async () => {
    expect(await getBook("missing")).toBeNull();
    expect(await markBookFinished("missing")).toBeNull();
  });
});

