:root {
  --paper: #f3efe6;
  --ink: #1c1915;
  --muted: #5c564e;
  --line: #d8d0c3;
  --cloth: #7c2f2a;
  --cloth-ink: #fff8f2;
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  border-top: 6px solid var(--cloth);
  background: var(--paper);
  color: var(--ink);
  font-family: "Iowan Old Style", Palatino, "Palatino Linotype", Georgia, serif;
  font-size: 1.0625rem;
  line-height: 1.5;
}

::selection {
  background: #e7c7b8;
}

.page {
  max-width: 40rem;
  margin: 0 auto;
  padding: 2.75rem 1.25rem 4.5rem;
}

h1,
h2 {
  font-weight: 550;
  letter-spacing: -0.02em;
  line-height: 1.15;
  overflow-wrap: anywhere;
}

h1 {
  margin: 0;
  font-size: 2.5rem;
}

h2 {
  margin: 0 0 0.9rem;
  font-size: 1.2rem;
}

a {
  color: inherit;
}

p {
  margin: 0;
}

.mast {
  margin-bottom: 0.5rem;
}

.lede,
.author,
.byline,
.when,
.empty,
.optional {
  color: var(--muted);
}

.lede {
  margin-top: 0.45rem;
}

.shelf {
  margin-top: 2.25rem;
  padding-top: 1.15rem;
  border-top: 1px solid var(--line);
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 1.15rem;
}

.book-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
}

.book-link {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
  text-decoration: none;
}

.book-title {
  font-size: 1.15rem;
  text-decoration: underline;
  text-decoration-color: var(--line);
  text-underline-offset: 0.18em;
}

.book-link:hover .book-title,
.back a:hover,
.share-url a:hover {
  color: var(--cloth);
  text-decoration-color: var(--cloth);
}

.author {
  font-size: 0.98rem;
}

.byline {
  margin-top: 0.45rem;
  font-size: 1.15rem;
}

.author-name {
  color: var(--ink);
}

.status,
.optional {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.status {
  margin: 1.4rem 0 0.35rem;
}

.when {
  margin-top: 0.35rem;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.9rem;
}

.back {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.92rem;
}

.notes {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.empty {
  font-style: italic;
}

.stack {
  display: grid;
  gap: 1rem;
}

label {
  display: grid;
  gap: 0.35rem;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.92rem;
}

input,
textarea {
  width: 100%;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  padding: 0.45rem 0;
  background: transparent;
  color: inherit;
  font: inherit;
}

textarea {
  border: 1px solid var(--line);
  padding: 0.65rem 0.7rem;
  resize: vertical;
  background: rgb(255 252 247 / 0.7);
}

button {
  justify-self: start;
  border: 0;
  background: var(--cloth);
  color: var(--cloth-ink);
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.92rem;
  line-height: 1.2;
  padding: 0.55rem 0.85rem;
  cursor: pointer;
}

button.quiet {
  background: transparent;
  color: var(--ink);
  border: 1px solid var(--line);
  white-space: nowrap;
}

input:focus,
textarea:focus,
button:focus-visible,
summary:focus-visible,
a:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 3px;
}

.error {
  margin-bottom: 0.8rem;
  color: var(--cloth);
  font-family: ui-sans-serif, system-ui, sans-serif;
}

.edit-notes {
  margin-top: 1rem;
}

.edit-notes summary {
  cursor: pointer;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.92rem;
}

.edit-notes form {
  margin-top: 0.9rem;
}

.finish-form {
  margin-top: 1.5rem;
}

.share-url {
  margin-top: 0.55rem;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.92rem;
  overflow-wrap: anywhere;
}

@media (max-width: 36rem) {
  .book-row {
    flex-direction: column;
  }

  button,
  button.quiet {
    width: 100%;
  }
}

