import Link from "next/link";
import { connection } from "next/server";
import { addBookAction, markFinishedAction } from "./actions";
import { finishedBooks, listBooks, readingBooks, type Book } from "../lib/books";

export const dynamic = "force-dynamic";

export default async function HomePage({
  searchParams,
}: {
  searchParams: Promise<{ error?: string }>;
}) {
  await connection();
  const { error } = await searchParams;
  const books = await listBooks();

  return (
    <main>
      <header className="mast">
        <h1>Books</h1>
        <p className="lede">Saved on this computer. No account.</p>
      </header>

      <section className="shelf" aria-labelledby="reading-heading">
        <h2 id="reading-heading">Currently reading</h2>
        <BookList books={readingBooks(books)} empty="Nothing in progress." showFinish />
      </section>

      <section className="shelf" aria-labelledby="finished-heading">
        <h2 id="finished-heading">Finished</h2>
        <BookList books={finishedBooks(books)} empty="Nothing finished yet." />
      </section>

      <section className="shelf" aria-labelledby="add-heading">
        <h2 id="add-heading">Add a book</h2>
        {error === "missing" ? (
          <p className="error" role="alert">
            Title and author are required.
          </p>
        ) : null}
        <form action={addBookAction} className="stack">
          <label>
            Title
            <input name="title" required maxLength={200} autoComplete="off" />
          </label>
          <label>
            Author
            <input name="author" required maxLength={200} autoComplete="off" />
          </label>
          <label>
            Notes <span className="optional">optional</span>
            <textarea name="notes" rows={4} maxLength={5000} />
          </label>
          <button type="submit">Add book</button>
        </form>
      </section>
    </main>
  );
}

function BookList({
  books,
  empty,
  showFinish = false,
}: {
  books: Book[];
  empty: string;
  showFinish?: boolean;
}) {
  if (books.length === 0) {
    return <p className="empty">{empty}</p>;
  }

  return (
    <ul className="book-list">
      {books.map((book) => (
        <li key={book.id} className="book-row">
          <Link href={`/books/${book.id}`} className="book-link">
            <span className="book-title">{book.title}</span>
            <span className="author">{book.author}</span>
          </Link>
          {showFinish ? (
            <form action={markFinishedAction}>
              <input type="hidden" name="id" value={book.id} />
              <input type="hidden" name="returnTo" value="/" />
              <button type="submit" className="quiet">
                Mark as finished
              </button>
            </form>
          ) : null}
        </li>
      ))}
    </ul>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { connection, headers } from "next/server";
import { markFinishedAction, updateNotesAction } from "../../actions";
import { getBook } from "../../../lib/books";

export const dynamic = "force-dynamic";

type BookPageProps = {
  params: Promise<{ id: string }>;
};

function formatWhen(iso: string | null): string | null {
  if (!iso) return null;
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return null;
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
  }).format(date);
}

async function shareUrl(id: string): Promise<string> {
  const headerList = await headers();
  const host = headerList.get("x-forwarded-host") ?? headerList.get("host");
  const proto = headerList.get("x-forwarded-proto") ?? "http";
  return host ? `${proto}://${host}/books/${id}` : `/books/${id}`;
}

export async function generateMetadata({ params }: BookPageProps): Promise<Metadata> {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) return { title: "Not found" };
  return {
    title: book.title,
    description: `${book.title} by ${book.author}`,
  };
}

export default async function BookPage({ params }: BookPageProps) {
  await connection();
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  const url = await shareUrl(book.id);
  const finishedOn = formatWhen(book.finishedAt);
  const reading = book.status === "reading";

  return (
    <main>
      <p className="back">
        <Link href="/">All books</Link>
      </p>
      <p className="status">{reading ? "Currently reading" : "Finished"}</p>
      <h1>{book.title}</h1>
      <p className="byline">
        by <span className="author-name">{book.author}</span>
      </p>
      {finishedOn ? <p className="when">Finished {finishedOn}</p> : null}

      <section className="shelf" aria-labelledby="notes-heading">
        <h2 id="notes-heading">Notes</h2>
        {book.notes ? (
          <p className="notes">{book.notes}</p>
        ) : (
          <p className="empty">No notes yet.</p>
        )}
        <details className="edit-notes">
          <summary>{book.notes ? "Edit notes" : "Add notes"}</summary>
          <form action={updateNotesAction} className="stack">
            <input type="hidden" name="id" value={book.id} />
            <label>
              Notes
              <textarea name="notes" rows={6} maxLength={5000} defaultValue={book.notes} />
            </label>
            <button type="submit">Save notes</button>
          </form>
        </details>
      </section>

      {reading ? (
        <form action={markFinishedAction} className="finish-form">
          <input type="hidden" name="id" value={book.id} />
          <input type="hidden" name="returnTo" value={`/books/${book.id}`} />
          <button type="submit">Mark as finished</button>
        </form>
      ) : null}

      <section className="shelf" aria-labelledby="share-heading">
        <h2 id="share-heading">Link</h2>
        <p className="lede">Send this address to open just this book.</p>
        <p className="share-url">
          <a href={url}>{url}</a>
        </p>
      </section>
    </main>
  );
}

