}

.edit-notes form {
  margin-top: 0.9rem;
}

.finish-form {
  margin-top: 1.5rem;
}

.share-url {
  margin-top: 0.55rem;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.92rem;
  overflow-wrap: anywhere;
}

@media (max-width: 36rem) {
  .book-row {
    flex-direction: column;
  }

  button,
  button.quiet {
    width: 100%;
  }
}

